import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 10 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"10","title":"Page 10 | Home","prev":"/page/9/","next":"/page/11/","posts":[{"title":"如何瘦身docker镜像","url":"/posts/2021-09-09-slim-docker-image/","date":"2021-09-09 21:44","tags":["docker"],"html":"<p>容器化部署已经成为现在的主流，打包 docker 镜像已经是现代前端开发的必修课了。最近正好在做新项目的时候处理过相关事情，所以记录一下。</p>\\n<h2 id=\\"docker-部署的需求\\" tabindex=\\"-1\\">docker 部署的需求 <a class=\\"header-anchor\\" href=\\"#docker-部署的需求\\" aria-label=\\"Permalink to &quot;docker 部署的需求&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先我们需要使用 docker 完成网站源代码的编译，并且还要自己使用 <a href=\\"https://expressjs.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">expressjs</a> 搭建服务器。让网站可以运行，docker 跑起来之后只用负责端口转发即可。</p>\\n<p>大家都知道前端网站编译需要安装很多依赖，但这些依赖在网站运行的时候并不需要。那如何才能做到，编译之后丢弃这些不用的依赖呢？ 我一开始尝试主动删除，但发现并没有减少 docker 的大小。</p>\\n<p>答案是<a href=\\"https://docs.docker.com/develop/develop-images/multistage-build/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Use multi-stage builds</a></p>\\n<h2 id=\\"编译网站\\" tabindex=\\"-1\\">编译网站 <a class=\\"header-anchor\\" href=\\"#编译网站\\" aria-label=\\"Permalink to &quot;编译网站&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先我们需要安装依赖并编译网站，dockerfile 内容如下：</p>\\n<div class=\\"language-dockerfile line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">dockerfile</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">FROM</span><span style=\\"color:#24292E\\"> node:14.17.5-buster-slim </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#24292E\\"> build</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ARG</span><span style=\\"color:#24292E\\"> GITHUB_PACKAGES_TOKEN</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> apt-get update &#x26;&#x26; apt-get install -y --no-install-recommends autoconf automake g++ libpng-dev make</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># use changes to package.json to force Docker not to use the cache</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># when we change our application's nodejs dependencies:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> package.json yarn.lock /tmp/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> echo $GITHUB_PACKAGES_TOKEN</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> cd /tmp &#x26;&#x26; yarn install --forzen-lockfile --production=false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> mkdir -p /app &#x26;&#x26; mv /tmp/node_modules /app</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># From here we load our application's code in, therefore the previous docker</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># \\"layer\\" thats been cached will be used if possible</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">WORKDIR</span><span style=\\"color:#24292E\\"> /app</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> . /app</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">ENV</span><span style=\\"color:#24292E\\"> NODE_ENV production</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> yarn build &#x26;&#x26; yarn express:build</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br></div></div><p>上面的命令编译了网站和 express 服务端代码，这里选择的 node 官方镜像并不是精简版，因为编译的时候需要很多依赖，精简版的话反而安装系统依赖更花时间。</p>\\n<h2 id=\\"安装依赖\\" tabindex=\\"-1\\">安装依赖 <a class=\\"header-anchor\\" href=\\"#安装依赖\\" aria-label=\\"Permalink to &quot;安装依赖&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>网站运行并不需要 node_modules 但是 express 服务器是需要的，所以我们需要安装后端的依赖。</p>\\n<div class=\\"language-dockerfile line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">dockerfile</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">FROM</span><span style=\\"color:#24292E\\"> node:14.17.5-alpine3.14 </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#24292E\\"> deps</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># use changes to package.json to force Docker not to use the cache</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\"># when we change our application's nodejs dependencies:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> server/package.json server/yarn.lock /tmp/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">RUN</span><span style=\\"color:#24292E\\"> cd /tmp &#x26;&#x26; yarn install --forzen-lockfile --production=false</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>服务端的 <code>package.json</code> 文件我放在了 server 文件夹下，服务端依赖的东西很少，所以不太占用空间。</p>\\n<h2 id=\\"打包实际生成的文件\\" tabindex=\\"-1\\">打包实际生成的文件 <a class=\\"header-anchor\\" href=\\"#打包实际生成的文件\\" aria-label=\\"Permalink to &quot;打包实际生成的文件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-dockerfile line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">dockerfile</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">FROM</span><span style=\\"color:#24292E\\"> node:14.17.5-alpine3.14</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">WORKDIR</span><span style=\\"color:#24292E\\"> /app</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> . /app</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> --from=deps /tmp/node_modules ./node_modules/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> --from=build /app/dist ./dist/</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">COPY</span><span style=\\"color:#24292E\\"> --from=build /app/server ./server/</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br></div></div><p>接下来的步骤很简单了， 选择占用空间最小的 <code>Alpine Linux</code> 然后把编译好的文件复制进来就可以了。前两个步骤的所有东西都会被丢弃掉。所以实际生成的 docker 镜像会非常小。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>采用多阶段编译，可以有效的减少编译的依赖对空间的占用，做到最小化 docker 镜像。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://learnk8s.io/blog/smaller-docker-images\\" target=\\"_blank\\" rel=\\"noreferrer\\">3 simple tricks for smaller Docker images</a></p>\\n"},{"title":"如何检测用户启动广告屏蔽插件","url":"/posts/2021-07-25-detect-ad-blocker/","date":"2021-07-25 14:32","tags":["ad"],"html":"<p>广告屏蔽插件让我们作为用户可以减少广告的打扰，但是作为开发者有时候因为用户开启了广告屏蔽导致网站收入减少或者影响了一部分功能的使用。我们不得不提示用户关闭广告插件，以正常使用网站。\\n但是针对不同的需求，广告的检测方式也不一样。我们接下来详细讲一讲。</p>\\n<h2 id=\\"网站本身投放广告\\" tabindex=\\"-1\\">网站本身投放广告 <a class=\\"header-anchor\\" href=\\"#网站本身投放广告\\" aria-label=\\"Permalink to &quot;网站本身投放广告&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>针对网站本身有投放广告的情况下，我们可以通过 JavaScript 来检查广告的 HTML 元素是否存在，以及 CSS 属性来判断。示例代码如下：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">node) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).display </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'none'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(node.parentElement);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isHidden</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).visibility </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'hidden'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isDisplayNone</span><span style=\\"color:#24292E\\">(node)) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br></div></div><p>通过检测广告元素是否被删除或者隐藏可以非常可靠的提示用户关闭广告插件或者其他操作。</p>\\n<h2 id=\\"网站由于广告屏蔽导致功能不全\\" tabindex=\\"-1\\">网站由于广告屏蔽导致功能不全 <a class=\\"header-anchor\\" href=\\"#网站由于广告屏蔽导致功能不全\\" aria-label=\\"Permalink to &quot;网站由于广告屏蔽导致功能不全&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>例如由于用户开启广告屏蔽插件，导致支付服务 <code>stripe</code> 无法正常使用。我们本身并没有在网站上发布广告。这时候可以使用网络请求的方式来检测广告屏蔽插件。示例代码如下：</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">  checkAdBlocker</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">   fetch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'https://pagead2.googlesyndication.com/pagead/show_ads.js'</span><span style=\\"color:#24292E\\">, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">     mode: </span><span style=\\"color:#032F62\\">'no-cors'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">   }).</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">     console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'Please disable ad blockers'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">   })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>原理很简单，广告屏蔽插件一定会阻止加载谷歌的 JavaScript 代码来屏蔽广告的执行，只要我们使用 <code>fetch</code> 方法来请求这个 JavaScript 文件，如果出错那就一定是使用了广告屏蔽插件。\\n所以同样的道理，如果因为有些图片的路径带上了 <code>ad</code> 之类的关键字导致被屏蔽，我们也可以使用这个方法来进行检测。记住这里需要开启 <code>no-cors</code> 模式，因为 JavaScript 的网络请求是受到同源策略的严格控制的。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>广告屏蔽插件的原理基本有三种，第一是有列表黑名单，出现在列表黑名单的资源都会直接被中断网络请求，例如无法加载图片，JavaScript 文件等等。第二是关键字匹配，如果资源文件里面有 <code>ad</code> 之类的相关广告关键字，那这个资源也会被中断请求。第三个是 DOM 检测，针对已经渲染好的 HTML 文件，通过 <code>class</code> 属性来检测是否有相关的广告关键字。如果符合结果，就删除相应的元素。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/sitexw/FuckAdBlock\\" target=\\"_blank\\" rel=\\"noreferrer\\">FuckAdBlock</a></p>\\n"},{"title":"ELK收集Docker项目的日志","url":"/posts/2021-06-14-elk-docker/","date":"2021-06-14 11:21","tags":["ELK docker"],"html":"<p>现在主流的项目部署都是采用 docker 部署了，一般项目使用 <code>STDOUT</code> 输出的日志都被 docker 来收集和保存。我们需要使用著名的 <a href=\\"https://www.elastic.co/what-is/elk-stack\\" target=\\"_blank\\" rel=\\"noreferrer\\">ELK</a> 来分析日志，所以如何部署 ELK 并且把 docker 的日志转发给 ELK 呢？ 这就是本篇文章我们需要解决的问题。</p>\\n<h2 id=\\"搭建-elk\\" tabindex=\\"-1\\">搭建 ELK <a class=\\"header-anchor\\" href=\\"#搭建-elk\\" aria-label=\\"Permalink to &quot;搭建 ELK&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>既然我们使用 docker 进行部署，那我们当然也要使用 docker 部署 ELK。<a href=\\"https://github.com/deviantony/docker-elk\\" target=\\"_blank\\" rel=\\"noreferrer\\">docker-elk</a> 是一个配置好的项目，我们可以基于这个项目迅速搭建起一个 ELK 项目。说实话， ELK 项目非常消耗内存，所以至少保证机器有 4GB 内存，否则可能会宕机。搭建好 ELK 之后，记得按照教程重新设置密码。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose exec -T elasticsearch bin/elasticsearch-setup-passwords auto --batch</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>初始化密码之后，并修改 <code>kibana</code> 和 <code>logstash</code> 的配置文件更新密码。最后再重启这两个服务：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose restart kibana logstash</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"使用-gelf-收集日志\\" tabindex=\\"-1\\">使用 GELF 收集日志 <a class=\\"header-anchor\\" href=\\"#使用-gelf-收集日志\\" aria-label=\\"Permalink to &quot;使用 GELF 收集日志&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://docs.graylog.org/en/4.0/pages/gelf.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">GELF</a> 是一个经典的日志格式并且 docker 原生支持这个格式，首先我们需要配置 <code>logstash</code> 采取这个格式来收集日志。</p>\\n<p>修改 <code>logstash/pipeline/logstash.conf</code> 文件的 input 部分：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>input {</span></span>\\n<span class=\\"line\\"><span>\\tbeats {</span></span>\\n<span class=\\"line\\"><span>\\t\\tport => 5044</span></span>\\n<span class=\\"line\\"><span>\\t}</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>\\tgelf {</span></span>\\n<span class=\\"line\\"><span>\\t\\tport => 5000</span></span>\\n<span class=\\"line\\"><span>\\t}</span></span>\\n<span class=\\"line\\"><span>}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这样收集 <code>gelf</code> 的端口就是 <code>5000</code> 默认使用 UDP 格式。修改配置之后别忘了重启 <code>logstash</code>。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$ docker-compose restart logstash</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来实际项目要把日志转发到 <code>ELK</code> 上，如果我们使用 <code>docker-compose.yml</code> 需要在当前的 <code>service</code> 上添加 <code>logging</code> 相关的配置：</p>\\n<div class=\\"language-yaml line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">yaml</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#22863A\\">logging</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">  driver</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">gelf</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">  options</span><span style=\\"color:#24292E\\">:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#22863A\\">    gelf-address</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">'udp://0.0.0.0:5000'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>如果你的 ELK 和 实际项目并不是在同一台主机上，记得修改 <code>0.0.0.0</code> 成相应的主机名或 IP 地址。这样配置之后就可以在 <code>kibana</code> 上查看收集到的日志了。\\n不过要记得配置 <code>Index patterns</code> 然后在 <code>Discover</code> 界面上就能看到日志记录了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>ELK 收集 docker 日志并不是很复杂，但是摸索的时候很难调试，例如 ELK 配置了 <code>gelf</code> 方法收集日志，但却找不到好的方法来测试这个接口是否正常。\\n我只是通过 <code>nmap</code> 命令来检测 5000 端口是否开放，并不知道是否正常运行。</p>\\n<p>扫描当前主机的 UDP 端口：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>nmap -sU 0.0.0.0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>启动项目的 docker 的时候还出现了警告信息 <code>warning: no logs are available with the 'gelf' log driver</code> 为了这个问题我查了半天，但发现\\n这个信息即使出现了也可以正常收集。浪费了不少时间。最终的解决方案总是很简单，但查找的过程中难免绕弯路。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/</a></p>\\n<p><a href=\\"https://www.nginx.com/blog/using-free-ssltls-certificates-from-lets-encrypt-with-nginx/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using Free Let’s Encrypt SSL/TLS Certificates with NGINX</a></p>\\n"}]},"relativePath":"page/10/index.md","filePath":"page/[page].md"}`),e={name:"page/10/index.md"};function l(p,o,r,c,t,i){return a(),n("div")}const u=s(e,[["render",l]]);export{b as __pageData,u as default};
